const CRISIS=/죽고\s*싶|자살|자해|사라지고\s*싶|끝내고\s*싶|살기\s*싫|살고\s*싶지/;
const lastI={};
function lwKwLines(text,max){
  text=String(text||'');
  if(CRISIS.test(text)) return [];
  const T=text.replace(NOISE,' ');
  const best={};
  for(const e of K){ if(best[e.g]) continue; const m=e.re.exec(T); if(m) best[e.g]={e:e,i:m.index}; }
  const hits=Object.keys(best).map(g=>best[g]).sort((a,b)=>a.i-b.i).slice(0,max||2);
  const h=new Date(Date.now()+9*36e5).getUTCHours(), night=(h>=21||h<4);
  return hits.map(x=>{ const L=x.e.L; let n=Math.random()*L.length|0; if(n===lastI[x.e.k]&&L.length>1) n=(n+1)%L.length; lastI[x.e.k]=n;
    let s=L[n]; if(x.e.g==='c'&&night) s+=' 다만 이 시간의 커피는 내일 아침으로 미뤄 두는 게 좋겠어요.'; return s; });
}
