  if(/아침/.test(text)||(!/점심|낮|오후|저녁|밤|새벽/.test(text)&&h>=5&&h<11)) return '좋은 아침이에요.';
  if(/점심|낮|오후/.test(text)||(!/저녁|밤|새벽/.test(text)&&h>=11&&h<18)) return '어서 와요. 오후의 서가는 조용해요.';
