const BWR=/왜.{0,10}(책|읽|독서|소설)|(책|독서|소설).{0,8}(왜|이유)/, BFR=/(어떤|어던|무슨|어느|뭐).{0,6}(책|소설|작품).{0,10}(제일|가장|최애|좋아)|(제일|가장|최애).{0,8}(책|소설|작품)/;
const TEA=[[/홍차|아쌈|얼그레이|다르질링|밀크\s*티/,'홍차','홍차는 진하고 든든해서 하루를 시작할 때 좋아요.','m'],[/녹차|센차|현미녹차|말차/,'녹차','녹차는 맑고 가벼워서 식사 뒤나 머리를 식힐 때 좋아요.','a'],[/우롱|오룡|동정/,'우롱','우롱은 여러 번 우릴수록 향이 열려서 오후에 좋아요.','a'],[/보이차|숙차/,'보이차','보이차는 깊고 둥글어서 저녁에 몸을 데워 줘요.','n'],[/캐모마일|허브\s*티|루이보스/,'캐모마일','캐모마일은 카페인이 없어서 잠들기 전에 좋아요.','n'],[/커피|콜드\s*브루|핸드\s*드립/,'커피','커피는 정성을 들인 한 잔이 하루의 첫 문장 같아요.','m'],[/(^|\s)차(?=\s|$|[?？랑와이가는을를에도])/,'차','차는 우려내는 시간이 있어서 마음도 함께 우러나요.','a']];
function lwChatAnswer(text){
  text=String(text||''); if(CRISIS.test(text)) return '';
  const T=text.replace(NOISE,' '), q=INTERR.test(text), ks=INC.filter(k=>k[0].test(T));
  const ch=CH.find(c=>c[0].test(T));
  if(ch&&(q||DIS.test(T))&&!BEST.test(T)) return pickV('ch_'+ch[1],WHY.test(T)?ch[3]:ch[2]);
  if(BWR.test(text)&&!/(^|\s)(나는|난|내가)/.test(text)) return pickV('bw',BW);
  if(BFR.test(text)&&!/(^|\s)(나는|난|내가)/.test(text)&&!RG.genji.test(T)) return pickV('bf',BF);
  const tks=TEA.filter(k=>k[0].test(T));
  if(q&&tks.length>1){ const h=HH(), bd=(h>=5&&h<12)?'m':(h>=12&&h<18)?'a':'n', pk=tks.find(k=>k[3]===bd)||tks.find(k=>k[3]==='a'&&k[1]!=='커피')||tks.find(k=>k[1]!=='커피')||tks[0]; return tks[0][2]+' '+tks[1][2]+' 지금 같은 '+(bd==='m'?'아침':bd==='a'?'오후':'밤')+'엔 '+pk[1]+' 쪽이에요.'+((bd==='n'&&pk[3]!=='n')?' 다만 밤이라 카페인은 살짝 걱정돼요.':'')+' 당신은 어느 쪽이에요?'; }
  if(q&&tks.length===1&&TEA.indexOf(tks[0])<6&&(PREF.test(text)||/좋아해|어때/.test(text))) return tks[0][2]+' 당신은 어떤 쪽이 끌려요?';
  if(q&&RG.genji.test(T)&&DIS.test(T)&&!BEST.test(T)) return pickV('qa_gw',GW);
  if(q&&(PREF.test(text)||ks.length)){
    if(RG.genji.test(T)) return pickV('qa_g',GQ);
    if(ks.length>1){ const h=HH(), nt=(h>=19||h<5), pk=ks.find(k=>!!k[3]===nt)||ks[0]; return ks[0][2]+' '+ks[1][2]+' 지금 같은 '+(nt?'밤':'낮')+'엔 '+pk[1]+' 쪽이에요. 당신은 어느 쪽이에요?'; }
    if(ks.length) return ks[0][2]+' 당신은 어떤 향을 자주 피워요?';
    if(RG.incense.test(T)) return pickV('qa_i',IQ);
    if(RG.perfume.test(T)) return pickV('qa_p',PQ);
    if(RG.tea.test(T)) return teaQ();
    if(RG.coffee.test(T)) return coffeeQ();
    if(RG.jp.test(T)) return JQ;
    if(RG.classic.test(T)) return classicQ();
    if(RG.self.test(T)) return pickV('qa_s',SQ);
  }
  if(INV.test(text)){ const tp=topicOf(T), h=HH();
    const night=/밤|새벽/.test(text)||(!/아침|점심|낮|오후|저녁/.test(text)&&(h>=21||h<4));
    const g=HELLO.test(text)?timeGreet(text)+' ':'';
    return (g+(night&&!g?'밤에 나누는 이야기는 유난히 깊어져요. ':'')+pickV('iv_'+tp,IV[tp]||IV.none)).trim(); }
  if(SHARE.test(text)&&/책|소설|작품|고전|겐지|읽/.test(text)&&!K.some(e=>e.k!=='book'&&e.k!=='classic'&&e.re.test(T))) return pickV('sh',SH);
  if(q&&/겐지|고전|소설|작가|인센스|선향|향기|책/.test(T)&&!/슬프|힘들|우울|외로|불안|화가|짜증|속상/.test(text)) return pickV('fb',FB);
  return '';
}
window.lwChatAnswer=lwChatAnswer;
const _cr2=window.cfReplyFor;
window.cfReplyFor=function(k,t,short){
  let ans='', lines=[];
  try{ ans=lwChatAnswer(t); }catch(e){ LQ.err(e); }
  if(!ans){ try{ if((S.settings.lowenaTaste||'some')!=='off') lines=lwKwLines(t,short?1:2); }catch(e){ LQ.err(e); } }
  window._lwKwHit=!!(ans||lines.length);
  let r; try{ r=_cr2.apply(this,arguments); } finally{ window._lwKwHit=false; }
  if(ans) return NEG.test(k||'')?(r+'\n'+ans):ans;
  return lines.length?(r+'\n'+lines.join('\n')):r;
};
